SELECT s1.`c0` AS `id`, s1.`c1` AS `other`, s1.`c2` AS `__weight` FROM (SELECT s2.`c0` AS `c0`, s2.`c4` AS `c1`, s2.`c8` AS `c2` FROM (SELECT s3.`c0` AS `c0`, s3.`c1` AS `c1`, s3.`c2` AS `c2`, s3.`c3` AS `c3`, s3.`c4` AS `c4`, s3.`c5` AS `c5`, s3.`c6` AS `c6`, s3.`c7` AS `c7`, (CAST(s3.`c3` AS BIGINT) * CAST(s3.`c7` AS BIGINT)) AS `c8` FROM (SELECT s4.`c0` AS `c0`, s4.`c1` AS `c1`, s4.`c2` AS `c2`, s4.`c3` AS `c3`, s5.`c0` AS `c4`, s5.`c1` AS `c5`, s5.`c2` AS `c6`, s5.`c3` AS `c7` FROM (SELECT `id` AS `c0`, `customer` AS `c1`, `amount` AS `c2`, `__weight` AS `c3` FROM `orders$delta`) AS s4 INNER JOIN (SELECT `id` AS `c0`, `customer` AS `c1`, `amount` AS `c2`, `__weight` AS `c3` FROM `orders$delta`) AS s5 ON (s4.`c1` = s5.`c1`)) AS s3) AS s2) AS s1
